-- IELTS example review: 43 fixes (see docs/ielts-review/examples-fixes-0273.md).
UPDATE ielts_examples SET sentence_en = 'Spending on healthcare increased by ten per cent between 2000 and 2010.', updated_at = CURRENT_TIMESTAMP
WHERE id = 'increase-2' AND sentence_en = 'Spending on healthcare increased by ten percent between 2000 and 2010.' AND sentence_zh = '2000 年至 2010 年间,医疗支出增加了百分之十。' AND target = 'increased';

UPDATE ielts_examples SET sentence_en = 'The figure continued to climb, reaching a peak of eighty per cent in 2015.', updated_at = CURRENT_TIMESTAMP
WHERE id = 'climb-1' AND sentence_en = 'The figure continued to climb, reaching a peak of eighty percent in 2015.' AND sentence_zh = '这一数字持续攀升,在 2015 年达到百分之八十的峰值。' AND target = 'climb';

UPDATE ielts_examples SET sentence_en = 'The proportion of women in the workforce rose from 30 to 45 per cent.', updated_at = CURRENT_TIMESTAMP
WHERE id = 'proportion-1' AND sentence_en = 'The proportion of women in the workforce rose from 30 to 45 percent.' AND sentence_zh = '劳动力中女性的比例从百分之三十上升到百分之四十五。' AND target = 'proportion';

UPDATE ielts_examples SET sentence_en = 'The unemployment rate remained below five per cent for most of the decade.', updated_at = CURRENT_TIMESTAMP
WHERE id = 'rate-1' AND sentence_en = 'The unemployment rate remained below five percent for most of the decade.' AND sentence_zh = '这十年的大部分时间里,失业率保持在百分之五以下。' AND target = 'rate';

UPDATE ielts_examples SET sentence_en = 'The average for the whole country was about twelve per cent.', updated_at = CURRENT_TIMESTAMP
WHERE id = 'average-1' AND sentence_en = 'The average for the whole country was about twelve percent.' AND sentence_zh = '全国的平均数约为百分之十二。' AND target = 'average';

UPDATE ielts_examples SET sentence_en = 'Sales in Japan and Korea rose by ten and fifteen per cent respectively.', updated_at = CURRENT_TIMESTAMP
WHERE id = 'respectively-1' AND sentence_en = 'Sales in Japan and Korea rose by ten and fifteen percent respectively.' AND sentence_zh = '日本和韩国的销售额分别增长了百分之十和百分之十五。' AND target = 'respectively';

UPDATE ielts_examples SET sentence_en = 'Nearly seventy per cent of households owned a car in 2010.', updated_at = CURRENT_TIMESTAMP
WHERE id = 'nearly-1' AND sentence_en = 'Nearly seventy percent of households owned a car in 2010.' AND sentence_zh = '2010 年,近百分之七十的家庭拥有汽车。' AND target = 'Nearly';

UPDATE ielts_examples SET sentence_en = 'Imported goods are subject to a tax of ten per cent.', updated_at = CURRENT_TIMESTAMP
WHERE id = 'be-subject-to-1' AND sentence_en = 'Imported goods are subject to a tax of ten percent.' AND sentence_zh = '进口商品须缴纳百分之十的税。' AND target = 'are subject to';

UPDATE ielts_examples SET sentence_zh = '这两个国家的数字在整个时期都不相上下。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'comparable-1' AND sentence_en = 'The figures for the two countries were comparable throughout the period.' AND sentence_zh = '这两个国家的数字在整个时期都是可比的。' AND target = 'comparable';

UPDATE ielts_examples SET sentence_en = 'Sales of e-books may surpass those of printed books by 2030.', updated_at = CURRENT_TIMESTAMP
WHERE id = 'surpass-1' AND sentence_en = 'Sales of online books may surpass those of printed ones by 2030.' AND sentence_zh = '到 2030 年,电子书销量可能超越纸质书。' AND target = 'surpass';

UPDATE ielts_examples SET sentence_zh = '这个小组由来自六所不同学校的二十名教师组成。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'comprise-1' AND sentence_en = 'The group comprises twenty teachers from six different schools.' AND sentence_zh = '这个小组包含来自六所不同学校的二十名教师。' AND target = 'comprises';

UPDATE ielts_examples SET sentence_en = 'A new bridge was constructed across the river during this period.', sentence_zh = '在此期间,河上建起了一座新桥。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'construct-1' AND sentence_en = 'A new bridge was constructed across the river between the two maps.' AND sentence_zh = '在两张地图所示时间之间,河上建造了一座新桥。' AND target = 'constructed';

UPDATE ielts_examples SET sentence_zh = '父母应该负起责任,教孩子懂礼貌。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'take-responsibility-for-1' AND sentence_en = 'Parents should take responsibility for teaching their children good manners.' AND sentence_zh = '父母应该负责教孩子良好的礼貌。' AND target = 'take responsibility for';

UPDATE ielts_examples SET sentence_zh = '医生建议老年人开始做一些温和的运动。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'take-up-1' AND sentence_en = 'Doctors advise older people to take up gentle forms of exercise.' AND sentence_zh = '医生建议老年人开始进行温和的运动。' AND target = 'take up';

UPDATE ielts_examples SET sentence_zh = '学习数学有助于孩子培养很强的分析能力。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'analytical-1' AND sentence_en = 'Studying mathematics helps children to develop strong analytical skills.' AND sentence_zh = '学习数学有助于孩子培养强大的分析能力。' AND target = 'analytical';

UPDATE ielts_examples SET sentence_zh = '家庭收入对孩子的学业成就有很大影响。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'achievement-1' AND sentence_en = 'Family income has a strong influence on a child''s achievement at school.' AND sentence_zh = '家庭收入对孩子在学校的成就有很大影响。' AND target = 'achievement';

UPDATE ielts_examples SET sentence_zh = '熟练掌握英语能为你带来许多机会。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'proficiency-1' AND sentence_en = 'A high level of proficiency in English can open many doors.' AND sentence_zh = '高水平的英语熟练度能打开许多大门。' AND target = 'proficiency';

UPDATE ielts_examples SET sentence_zh = '每所学校都需要足够多合格的科学和数学教师。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'qualified-1' AND sentence_en = 'Every school needs enough qualified teachers in science and mathematics.' AND sentence_zh = '每所学校都需要足够的合格的科学和数学教师。' AND target = 'qualified';

UPDATE ielts_examples SET sentence_zh = '我们越来越依赖技术,这可能削弱我们的基本技能。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'dependence-1' AND sentence_en = 'Our growing dependence on technology may reduce our basic skills.' AND sentence_zh = '我们对技术日益增长的依赖可能削弱基本技能。' AND target = 'dependence';

UPDATE ielts_examples SET sentence_zh = '许多工人非常担心自动化会让自己的工作岗位被替代。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'job-displacement-1' AND sentence_en = 'Job displacement caused by automation is a serious concern for many workers.' AND sentence_zh = '自动化造成的工作岗位被替代是许多工人严重担忧的问题。' AND target = 'Job displacement';

UPDATE ielts_examples SET sentence_zh = '电视上的暴力内容越来越多,令人不安。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'disturbing-1' AND sentence_en = 'There is a disturbing rise in the amount of violence on television.' AND sentence_zh = '电视上的暴力内容令人不安地增多了。' AND target = 'disturbing';

UPDATE ielts_examples SET sentence_zh = '手机的盛行改变了年轻人打发时间的方式。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'prevalence-1' AND sentence_en = 'The prevalence of mobile phones has changed how young people spend their time.' AND sentence_zh = '手机的盛行改变了年轻人度过时间的方式。' AND target = 'prevalence';

UPDATE ielts_examples SET sentence_en = 'Wealthy nations should do more to help refugees build a new life.', sentence_zh = '富裕国家应该做更多的事,帮助难民开始新生活。', target = 'refugees', updated_at = CURRENT_TIMESTAMP
WHERE id = 'refugee-1' AND sentence_en = 'Wealthy nations should do more to help each refugee build a new life.' AND sentence_zh = '富裕国家应该做更多的事,帮助每位难民开始新生活。' AND target = 'refugee';

UPDATE ielts_examples SET sentence_en = 'Too much public money is spent on armaments rather than on schools.', target = 'armaments', updated_at = CURRENT_TIMESTAMP
WHERE id = 'armament-1' AND sentence_en = 'Too much public money is spent on armament rather than on schools.' AND sentence_zh = '太多公共资金花在军备上,而不是学校上。' AND target = 'armament';

UPDATE ielts_examples SET sentence_zh = '激进武装组织袭击了该国北部的政府建筑。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'militant-1' AND sentence_en = 'Militant groups have attacked government buildings in the north of the country.' AND sentence_zh = '好战团体袭击了该国北部的政府建筑。' AND target = 'Militant';

UPDATE ielts_examples SET sentence_zh = '批评者指责政府忽视农村社区的需求。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'accuse-1' AND sentence_en = 'Critics accuse the government of ignoring the needs of rural communities.' AND sentence_zh = '批评者指控政府忽视农村社区的需求。' AND target = 'accuse';

UPDATE ielts_examples SET sentence_zh = '对儿童的任何暴力行为,社会都绝不应纵容。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'condone-1' AND sentence_en = 'Society should never condone violence against children in any form.' AND sentence_zh = '社会绝不应纵容任何形式的针对儿童的暴力。' AND target = 'condone';

UPDATE ielts_examples SET sentence_en = 'Protesters claimed that the new government was illegitimate because the election had been rigged.', sentence_zh = '抗议者称,由于选举被操纵,新政府是非法的。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'illegitimate-1' AND sentence_en = 'Protesters claimed that the new government was illegitimate after a false election.' AND sentence_zh = '抗议者称,虚假选举后产生的新政府是非法的。' AND target = 'illegitimate';

UPDATE ielts_examples SET sentence_en = 'Tax evasion costs governments billions of pounds in lost revenue every year.', sentence_zh = '逃税每年使各国政府损失数十亿英镑的税收。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'tax-evasion-1' AND sentence_en = 'Tax evasion costs governments billions of pounds in lost money every year.' AND sentence_zh = '逃税每年使各国政府损失数十亿英镑。' AND target = 'Tax evasion';

UPDATE ielts_examples SET sentence_en = 'The police managed to free the hostage after several hours of negotiations.', updated_at = CURRENT_TIMESTAMP
WHERE id = 'hostage-1' AND sentence_en = 'The police managed to free the hostage after several hours of discussions.' AND sentence_zh = '经过几小时的谈判,警方成功解救了人质。' AND target = 'hostage';

UPDATE ielts_examples SET sentence_zh = '空气污染是大城市居民患呼吸系统疾病的主要原因。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'air-pollution-1' AND sentence_en = 'Air pollution is a major cause of breathing problems in large cities.' AND sentence_zh = '空气污染是大城市呼吸问题的主要原因。' AND target = 'Air pollution';

UPDATE ielts_examples SET sentence_en = 'Poor countries are often the worst affected by natural disasters.', target = 'natural disasters', updated_at = CURRENT_TIMESTAMP
WHERE id = 'natural-disaster-1' AND sentence_en = 'Poor countries are often the worst affected by a natural disaster.' AND sentence_zh = '贫穷国家往往受自然灾害的影响最严重。' AND target = 'natural disaster';

UPDATE ielts_examples SET sentence_zh = '沉船残骸漏出的石油沿海岸扩散了许多英里。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'wreck-1' AND sentence_en = 'Oil from the wreck spread along the coast for many miles.' AND sentence_zh = '残骸漏出的石油沿海岸扩散了许多英里。' AND target = 'wreck';

UPDATE ielts_examples SET sentence_zh = '在许多国家,老年人独居已成为常态。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'norm-1' AND sentence_en = 'Living alone has become the norm for older people in many countries.' AND sentence_zh = '在许多国家,老年人独居已成为一种规范。' AND target = 'norm';

UPDATE ielts_examples SET sentence_en = 'The intangible benefits of the arts are often difficult to measure in money.', target = 'intangible', updated_at = CURRENT_TIMESTAMP
WHERE id = 'intangible-1' AND sentence_en = 'Intangible benefits of the arts are often difficult to measure in money.' AND sentence_zh = '艺术无形的益处往往很难用金钱衡量。' AND target = 'Intangible';

UPDATE ielts_examples SET sentence_zh = '这位艺术家为首都的一座公共建筑画了这幅巨幅画作。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'canvas-1' AND sentence_en = 'The artist painted the huge canvas for a public building in the capital.' AND sentence_zh = '这位艺术家为首都的一座公共建筑绘制了这幅巨大的画布作品。' AND target = 'canvas';

UPDATE ielts_examples SET sentence_zh = '这位画家只用了蓝色和灰色等少数几种颜色。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'palette-1' AND sentence_en = 'The painter used a limited palette of blues and greys.' AND sentence_zh = '这位画家使用了以蓝色和灰色为主的有限调色板。' AND target = 'palette';

UPDATE ielts_examples SET sentence_en = 'Each new hotel creates job opportunities for people living nearby.', target = 'job opportunities', updated_at = CURRENT_TIMESTAMP
WHERE id = 'job-opportunity-1' AND sentence_en = 'Each new hotel creates a job opportunity for people living nearby.' AND sentence_zh = '每家新酒店都为附近居民创造就业机会。' AND target = 'job opportunity';

UPDATE ielts_examples SET sentence_zh = '技术可能让家庭关系变得不那么亲密。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'intimacy-1' AND sentence_en = 'Technology may reduce the intimacy of family relationships.' AND sentence_zh = '技术可能减少家庭关系的亲密。' AND target = 'intimacy';

UPDATE ielts_examples SET sentence_zh = '财务问题是引发婚姻矛盾的常见原因。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'marital-1' AND sentence_en = 'Financial problems are a common cause of marital difficulties.' AND sentence_zh = '财务问题是婚姻困难的常见原因。' AND target = 'marital';

UPDATE ielts_examples SET sentence_zh = '在许多发展中国家,孕产妇的健康状况大大改善。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'maternal-1' AND sentence_en = 'Maternal health has improved greatly in many developing countries.' AND sentence_zh = '在许多发展中国家,母亲的健康状况大大改善。' AND target = 'Maternal';

UPDATE ielts_examples SET sentence_zh = '有些人不吃任何含化学防腐剂的食品。', updated_at = CURRENT_TIMESTAMP
WHERE id = 'preservative-1' AND sentence_en = 'Some people avoid any food containing a chemical preservative.' AND sentence_zh = '有些人避免吃含有化学防腐剂的任何食品。' AND target = 'preservative';

UPDATE ielts_examples SET sentence_en = 'The number of people who train as tailors has fallen sharply.', target = 'tailors', updated_at = CURRENT_TIMESTAMP
WHERE id = 'tailor-1' AND sentence_en = 'The number of people who train as a tailor has fallen sharply.' AND sentence_zh = '接受裁缝培训的人数急剧下降。' AND target = 'tailor';
